// Chunk 51, e1a#1 (the trace verifier's test). Alice's Seedelf name puts her
// register (g, u) on chain for anyone to read. Mallory re-randomizes it with a
// d of her own, from those two points alone, and deposits one 5 ₳ box under it
// into v2's 5 ₳ pool, paid from her own address. The wallet's ownership check
// is b = [x]·a alone (wasm lovejoin.rs owned_in, core PoolBox::is_owned), so
// it counts the box as Alice's. Koios says a deposit made it, with no input
// under any key of the phrase (madeBy: { mixed: false }, no `public`), so the
// pool read holds it as not mixed yet (depositsOf), and the page says "Mix my
// boxes again takes it first". Today againBoxes keeps it (privately drops only
// a public account's boxes), fanOut sorts it first, and WebAssembly mixes
// ours[..boxes]: a mix the new one-time account pays, funded from Alice's
// private balance, spends Mallory's box. Mallory, watching her box, learns
// that account, and so its funding's private UTxOs and change, are the
// name's owner's.
//
// What's right (the finding's fix; the owner's call on the words and the way
// out): Mix my boxes again from the private balance never takes a box no key
// of the phrase paid in, as it never takes a public account's, so the chain
// mixes the wallet's own box and leaves Mallory's alone. Driven through the
// worker with the real WebAssembly, as lovejoin-restore.test.ts's "mixes
// again from the private balance a session deposit's box first" is.

import { describe, expect, it } from "vitest";

import { txInputs } from "../src/background/cbor";
import { Collateral } from "../src/background/collateral";
import { LovejoinService } from "../src/background/lovejoin";
import { Minswap } from "../src/background/minswap";
import { SessionService } from "../src/background/sessions";
import { account, AGREES, atSession, CHAINS, PASSWORD } from "./chain-fixtures";
import { preprodAddress } from "./fixtures/bech32";
import { txIdOf } from "./fixtures/cbor";
import { loadTestWasm, sessionSwap, testBalances, withdrawPreprod } from "./fakes";
import { ADA, ADA_ADDRESS, ADA_POOL, ADA_ROWS, ADA_VIEW, adaBox, ownDatum } from "./v2-pools";

const hash = (h: string) => (h.length === 64 ? h : h.repeat(32));

describe("r51 e1a#1: a stranger's deposit under the wallet's Seedelf register", CHAINS, () => {
  it("Mix my boxes again from the private balance never spends a box a stranger's deposit put in", async () => {
    const t = testBalances({ pools: [ADA_POOL] });
    await t.wallet.create(account(12).phrase, PASSWORD);
    const spend = withdrawPreprod.amount.evaluation as { result: unknown[] };
    t.koios.evaluation = (body: { params: { additionalUtxo?: unknown[] } }) =>
      body.params.additionalUtxo ? AGREES : { ...spend, result: spend.result.slice(0, 1) };
    // Ten others' boxes in the 5 ₳ pool: two waves deep, one box of the wallet's is mixed again at a time.
    const others = ADA_ROWS.slice(0, 10);
    t.koios.addedToAccounts.push(...others);
    t.collateral.answer = { status: 200, body: { witness: "a1008182" } };

    const wasm = loadTestWasm();
    // The Seedelf name's register, as anyone reads it from the name's UTxO: two public points, nothing secret.
    const name = await t.wallet.withKeys((keys) => {
      const r = wasm.rerandomize(keys.seedelf.baseRegister());
      return { generator: r.generator, publicValue: r.publicValue };
    });
    // Mallory's box: that register re-randomized with her own d, from the points alone.
    const planted = Buffer.from(wasm.registerToDatum(wasm.rerandomize(new wasm.Register(name.generator, name.publicValue)))).toString(
      "hex",
    );
    const [P, M] = [hash("e1"), hash("b1")];
    t.koios.addedToAccounts.push(adaBox(P, planted, t.clock.now), adaBox(M, await ownDatum(t.wallet), t.clock.now));
    // Her deposit, paid from her own address: a key no account or session of the phrase holds.
    const mallory = "ee".repeat(28);
    t.koios.txSpends.set(P, [{ payment_addr: { bech32: preprodAddress(mallory), cred: mallory } }]);
    // The wallet's own box, which a mix in the pool made.
    t.koios.txSpends.set(M, [
      { payment_addr: { bech32: ADA_ADDRESS, cred: ADA_VIEW.mixBoxHash } },
      { payment_addr: { bech32: sessionSwap.address, cred: sessionSwap.keyHash } },
    ]);

    const collateral = () => new Collateral("https://www.giveme.my/preprod/collateral/", t.collateral.fetch);
    const lovejoin: LovejoinService = new LovejoinService({
      ...t.deps,
      collateral,
      store: t.store,
      mixingAgain: (network) => sessions.mixingAgain(network),
      pools: async () => [ADA_POOL],
    });
    const sessions: SessionService = new SessionService({
      ...t.deps,
      // giveme.my's witness and the one-time key's signature stood in for, as sessions.test.ts does.
      wasm: {
        ...wasm,
        signScriptSpend: (_key: unknown, request: string) => {
          const { txCbor } = JSON.parse(request) as { txCbor: string };
          return JSON.stringify({ txCbor, txHash: txIdOf(Uint8Array.from(Buffer.from(txCbor, "hex"))) });
        },
      } as typeof wasm,
      collateral,
      store: t.store,
      minswap: () => new Minswap("https://aggr.monorepo-testnet-preprod.minswap.org/aggregator", t.minswap.fetch),
      lovejoin,
      sleep: async () => undefined,
    });

    // The pool read the Lovejoin page makes: Koios is asked what made each box.
    const status = (await lovejoin.status("preprod")).pools!.find((p) => p.id === ADA)!;
    console.log("pool read: not mixed yet", JSON.stringify(status.notMixed), "from a public account", JSON.stringify(status.fromPublic));

    // Mix my boxes again, from the private balance: its funding pays a new one-time account.
    const out = await sessions.againBuild("preprod", false, ADA);
    console.log("againBuild's mix", JSON.stringify(out.mix));
    await sessions.mixOutSubmit("preprod", out.txHash);
    t.koios.addedToAccounts.push(atSession(out.txHash, 0, out.payments[0]!.lovelace), atSession(out.txHash, 1, "5000000"));
    t.koios.confirmations = 1;
    t.koios.evaluation = AGREES;
    const before = t.koios.submitted.length;
    await sessions.advance("preprod", 0, true);
    const chain = t.koios.submitted.slice(before).map((tx) => ({ hash: txIdOf(tx), inputs: txInputs(tx) }));
    expect(chain.length).toBeGreaterThan(0);

    // Each input of a transaction the session sent, by whose it is.
    const theirs = new Set(others.map((u) => `${u.tx_hash}#${u.tx_index}`));
    const label = (i: string) =>
      i === `${P}#0`
        ? "Mallory's box"
        : i === `${M}#0`
          ? "the wallet's own box"
          : i.startsWith(`${out.txHash}#`)
            ? "the one-time account's funding, paid from the private balance"
            : chain.some((tx) => i.startsWith(`${tx.hash}#`))
              ? "the one-time account's change from an earlier mix"
              : theirs.has(i)
                ? "another's box"
                : i;
    const takers = chain.filter((tx) => tx.inputs.includes(`${P}#0`)).map((tx) => tx.inputs.map(label).sort());
    // No transaction the one-time account pays spends Mallory's box...
    expect(takers).toEqual([]);
    // ...and the wallet's own box is still mixed again.
    expect(chain.flatMap((tx) => tx.inputs.map(label))).toContain("the wallet's own box");
  });
});

// Chunk 51, e3a#1 (the trace verifier's test). A site connected on the public
// side talks to the dApp account, Settings' choice (Account 1 by default),
// whichever account the wallet is working on (dapp.ts withDappKeys). A mix
// from the public side is built and signed by the active account
// (lovejoin.ts publicBuild, readAccount), but reserved under the one owner
// "public", whichever account pays (chainOwner(), at its review and at Send).
// signTx's first look (heldForLovejoin, chainHeld) reads that reservation
// whole. So while Account 2 sends a mix, a site on Account 1 that names one
// of that chain's UTxOs (Account 2's own, its collateral, a pool box it
// draws) is refused as "a Lovejoin chain still holds" it, where a stranger's
// UTxO hears "Nothing in this transaction is the public account's to sign".
// privacy.md (Connecting a site) promises the opposite: "a signature is
// checked only against its own account's Lovejoin chain … Anything else …
// gets the stranger's answer". This asserts the promise: it fails today.
import { describe, expect, it } from "vitest";

import { type DappSession } from "../src/background/dapp";
import { chainOwner, SESSION_LOVEJOIN_PUBLIC } from "../src/background/lovejoin";
import { reservations } from "../src/background/spent";
import { TxSignError } from "../src/shared/dapp";
import { chainNet, publicFunded, type Tested } from "./chain-fixtures";
import { koiosPreprod, loadTestWasm, vectors } from "./fakes";
import { ADA, ADA_ROWS } from "./v2-pools";

/** A real chain, built and measured in WebAssembly. */
const CHAINS = { timeout: 180_000 };

/** Someone else's address: the 15-word phrase's. */
const THEIRS = vectors("cardano_account.json").find((v) => v.account === 0 && v.phrase.split(" ").length === 15)!.preprod
  .receive_0 as string;

let pages = 0;
const site = (): DappSession => ({ id: `r51e3a1-${++pages}`, origin: "https://app.example.com", title: "Example" });

async function until(check: () => boolean) {
  for (let i = 0; i < 200 && !check(); i++) await new Promise((r) => setTimeout(r, 0));
  expect(check()).toBe(true);
}

const uint = (n: number) => (n < 24 ? n.toString(16).padStart(2, "0") : `18${n.toString(16).padStart(2, "0")}`);
const outpoints = (list: string[]) => `8${list.length}${list.map((o) => `825820${o.slice(0, 64)}${uint(Number(o.slice(65)))}`).join("")}`;

/** A site's transaction spending `inputs` and putting up `collateral`, paying 4 ₳ to someone else: read, never balanced. */
function siteTx(inputs: string[], collateral: string[] = []) {
  const pay = `825839${loadTestWasm().cip30Address(THEIRS)}1a003d0900`;
  const fields = [`00${outpoints(inputs)}`, `0181${pay}`, "021a00029810", ...(collateral.length ? [`0d${outpoints(collateral)}`] : [])];
  return `84a${fields.length}${fields.join("")}a0f5f6`;
}

/** Public account `index` known, with a 5 ₳ collateral (`f5…#0`) and 60 ₳ (`f6…#0`) of its own. */
async function fundAccount(t: Tested, index: number) {
  await t.accounts.add(index);
  const { key, address } = await t.wallet.withAccount(index, (k) => ({
    key: k.cardano.paymentKeyHash(0, 0),
    address: k.cardano.receiveAddress(t.deps.wasm.Network.Preprod, 0),
  }));
  const [first] = Object.values(koiosPreprod.accounts)[0]!.account_utxos.filter((u) => BigInt(u.value) > 1_000_000_000n);
  const at = (tx: string, value: string) => ({ ...first!, tx_hash: tx.repeat(32), tx_index: 0, value, address, payment_cred: key, asset_list: [] });
  t.koios.addedToAccounts.push(at("f5", "5000000"), at("f6", "60000000"));
  return { collateral: `${"f5".repeat(32)}#0`, funds: `${"f6".repeat(32)}#0` };
}

describe("r51 e3a#1: a site on the dApp account while another public account sends a Lovejoin mix", CHAINS, () => {
  it("hears a stranger's answer for what that account's chain holds, as privacy.md promises", async () => {
    // Account 1 (index 0) is the dApp account, Settings' default; Account 2 (index 1) has money of its own.
    const t = await publicFunded();
    await t.accounts.recordFirst();
    await t.preferences.set({ dappConnector: true, dappPassword: false, spendRewards: false, lovejoinDepth: 1 });
    const two = await fundAccount(t, 1);

    // A site connects on the public side: it talks to Account 1.
    const s = site();
    const enabling = t.dapp.call(s, "enable", []);
    await until(() => t.dapp.approvals().length === 1);
    await t.dapp.answer(t.dapp.approvals()[0]!.id, true);
    expect(await enabling).toBe(true);

    // The user works on Account 2 and sends a mix from the public account through Lovejoin's 5 ₳ pool: four boxes,
    // five transactions, so the first window leaves some of it to send (a chain of four or fewer goes whole at Send).
    await t.accounts.use(1, ["preprod"]);
    expect((await t.preferences.get()).dappAccount).toBe(0);
    const summary = await t.lovejoin.publicBuild("preprod", 4, { pool: ADA });
    const kept = await t.wallet.withKeys(() => t.session.get<{ chain: Array<{ txHash: string }> }>(SESSION_LOVEJOIN_PUBLIC));
    const order = kept!.chain.map((c) => c.txHash);
    expect(order).toHaveLength(5);
    const net = chainNet(t, () => order);
    await t.lovejoin.publicSubmit("preprod", summary.txHash);
    expect(net.mempool.length).toBeGreaterThan(0);
    expect(net.mempool.length).toBeLessThan(5);
    const { chains } = (await t.store.get<{ chains: Array<{ id: string; account?: number }> }>("lovejoin.preprod"))!;
    expect(chains.find((c) => c.id === summary.txHash)?.account).toBe(1);

    // What Account 2's chain holds while it's being sent: its UTxO, its collateral and the pool boxes it draws, under "public".
    const held = (await t.wallet.withKeys(() => reservations(t.session, "preprod", t.clock.now)))[chainOwner()]!;
    expect(held.until).toBeUndefined();
    expect(held.inputs).toContain(two.funds);
    expect(held.collateral).toContain(two.collateral);
    const rows = new Set(ADA_ROWS.map((u) => `${u.tx_hash}#${u.tx_index}`));
    const box = held.inputs.find((o) => rows.has(o));
    expect(box).toBeDefined();

    // What the site hears for a transaction naming each. None is Account 1's to sign.
    const answer = async (inputs: string[], collateral: string[] = []) => {
      const failure = await t.dapp.call(s, "signTx", [siteTx(inputs, collateral), false]).then(
        () => undefined,
        (e: { failure?: unknown }) => e.failure ?? String(e),
      );
      // A fresh minute of the site's lookups for the next (dapp.ts PER_MINUTE).
      t.clock.now += 61_000;
      return failure;
    };
    const strangers = { code: TxSignError.ProofGeneration, info: "Nothing in this transaction is the public account's to sign." };
    const stranger = `${"cd".repeat(32)}#0`;
    expect(await answer([stranger])).toEqual(strangers);
    const heard = {
      "Account 2's UTxO": await answer([two.funds]),
      "a pool box the chain draws": await answer([box!]),
      "Account 2's collateral": await answer([stranger], [two.collateral]),
    };
    expect(heard).toEqual({
      "Account 2's UTxO": strangers,
      "a pool box the chain draws": strangers,
      "Account 2's collateral": strangers,
    });
    expect(t.dapp.approvals()).toEqual([]);
  });
});

// Chunk 51, finding e3a#3 (also e3b#1): a site's signData message reaches the
// connector's window with direction overrides and invisible characters still
// in it. readableText (background/dapp.ts) refuses only C0 controls but tab,
// LF and CR, and DEL, so "Pay U+202E 0001 U+202C ADA" keeps its override, and
// SignData (ui/screens/DappApprovals.tsx) shows the text, without the hex, in a
// <pre> whose `unicode-bidi: isolate` keeps it from reordering what's around
// it, not what's inside: the window reads "Pay 1000 ADA" over bytes that say
// 0001. A zero-width space makes "nonce 4<ZWSP>2" read as "nonce 42".
// Everywhere else the wallet shows a site's or the chain's text it strips or
// escapes these (siteTitle, governance.ts shownText, decode.rs shown,
// ui/tokens.ts HIDDEN). The worker's approval, rendered as the window renders
// it, should carry none of them raw: escaped as decode.rs writes them, left
// out, or the hex in the text's place. The real WebAssembly and fakes of
// Koios, as dapp.test.ts' signData case.
import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { describe, expect, it } from "vitest";

import { type DappSession } from "../src/background/dapp";
import { DataSignError } from "../src/shared/dapp";
import { SignData } from "../src/ui/screens/DappApprovals";
import { testBalances, vectors } from "./fakes";

const PASSWORD = "correct horse battery";
const account = (words: number) =>
  vectors("cardano_account.json").find((v) => v.account === 0 && v.phrase.split(" ").length === words)!;
const OWN = account(12).preprod.receive_0 as string;
const hex = (text: string) => Buffer.from(text, "utf8").toString("hex");
const site = (): DappSession => ({ id: "r51e3a3", origin: "https://app.example.com", title: "Example" });

/** Right-to-left override, pop directional formatting, zero-width space. */
const RLO = String.fromCodePoint(0x202e);
const PDF = String.fromCodePoint(0x202c);
const ZWSP = String.fromCodePoint(0x200b);

/**
 * What changes how text reads without showing: Unicode's Cf and Default_Ignorable_Code_Point (ui/tokens.ts HIDDEN),
 * the C0 and C1 controls but the tab and line breaks the window keeps, and U+2028/2029 (decode.rs hidden()).
 */
const HIDDEN = /[\p{Cf}\p{Default_Ignorable_Code_Point}\p{Cc}\p{Zl}\p{Zp}]/u;
const KEPT = new Set([0x09, 0x0a, 0x0d]);
const hidden = (c: string) => HIDDEN.test(c) && !KEPT.has(c.codePointAt(0)!);
const named = (text: string) =>
  [...text].filter(hidden).map((c) => `U+${c.codePointAt(0)!.toString(16).toUpperCase().padStart(4, "0")}`);
/** Whether every character of `want` is in `text`, in order: the message is still there to read. */
const inOrder = (want: string, text: string) => {
  let i = 0;
  for (const c of text) if (c === want[i]) i++;
  return i === want.length;
};

async function until(check: () => boolean) {
  for (let i = 0; i < 200 && !check(); i++) await new Promise((r) => setTimeout(r, 0));
  expect(check()).toBe(true);
}

describe("a site's signData message with direction or invisible characters (chunk 51, e3a#3)", () => {
  it("is shown in the window with none of them raw, so it can't read as other than its bytes", async () => {
    const t = testBalances();
    await t.wallet.create(account(12).phrase, PASSWORD);
    await t.preferences.set({ dappConnector: true, spendRewards: false });
    const s = site();
    const enabling = t.dapp.call(s, "enable", []);
    await until(() => t.dapp.approvals().length === 1);
    await t.dapp.answer(t.dapp.approvals()[0]!.id, true);
    expect(await enabling).toBe(true);

    const messages = [
      // Reads "Pay 1000 ADA for order 77" in the window: the override reverses 0001.
      `Pay ${RLO}0001${PDF} ADA for order 77`,
      // Reads "Sign in: nonce 42".
      `Sign in: nonce 4${ZWSP}2`,
    ];
    const results: Array<{ raw: string[]; says: boolean }> = [];
    for (const message of messages) {
      const signing = t.dapp.call(s, "signData", [t.deps.wasm.cip30Address(OWN), hex(message)]);
      signing.catch(() => undefined);
      await until(() => t.dapp.approvals().length === 1);
      const a = t.dapp.approvals()[0]!;
      if (a.kind !== "sign-data") throw new Error(`a sign-data approval, not ${a.kind}`);
      // As DappApprovals.tsx renders it.
      const html = renderToStaticMarkup(
        createElement(SignData, { address: a.address, signer: a.key, payload: a.payload, text: a.text }),
      );
      const shown = /data-testid="dapp-data-message">([\s\S]*?)<\/pre>/.exec(html)?.[1];
      expect(shown).toBeDefined();
      const visible = [...message].filter((c) => !hidden(c)).join("");
      results.push({ raw: named(shown!), says: shown === a.payload || inOrder(visible, shown!) });
      await t.dapp.answer(a.id, false);
      await expect(signing).rejects.toMatchObject({ failure: { code: DataSignError.UserDeclined } });
    }
    expect(results).toEqual([
      { raw: [], says: true },
      { raw: [], says: true },
    ]);
  });
});

// Chunk 51, e6#1: a stranger can plant a Seedelf so Remove starts on the public account and says it "links nothing
// new". The mint policy at 5b82530 is open and checks no output, and every Seedelf's register is public through its
// name. So anyone can mint a Seedelf of their own under a fresh re-randomization of the user's register, and pay the
// user's public account 1 ₳ in the same transaction. The wallet lists that Seedelf as the user's. With no record of
// who paid, it takes the stranger's payment to the account (a UTxO from the mint, or Public activity's "received"
// entry for it) for an account-paid mint's change (minted-by.ts paidByOf). Remove then starts on the public account:
// "your public account paid for it, so this links nothing new". Sent there, the freed ADA shows that whoever holds the
// planted register (the stranger knows it's the owner of the user's Seedelf) holds the account.
//
// The right behaviour, which this asserts: a transaction that only paid the account says nothing about who paid for
// the Seedelf. So the wallet doesn't claim the account did, and Remove doesn't choose the public account for the user.
import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { describe, expect, it } from "vitest";

import { SESSION_ACCOUNT_ADDRESSES_PREFIX, type AccountAddresses } from "../src/background/activity";
import { CONTRACT_V1 } from "../src/background/balances";
import { registerOf } from "../src/background/chain";
import type { KoiosTxInfo, KoiosUtxo } from "../src/background/koios";
import type { SeedelfInfo } from "../src/shared/rpc";
import { RemoveSeedelf } from "../src/ui/screens/RemoveSeedelf";
import { activityPreprod, koiosPreprod, loadTestWasm, ownedUtxos, testBalances, vectors } from "./fakes";

const PASSWORD = "correct horse battery";
const phrase12 = () => vectors("cardano_account.json").find((v) => v.account === 0 && v.phrase.split(" ").length === 12)!;

/** The user's own Seedelf ("web-wallet"): its UTxO, whose register anyone reads through its name. */
const theirs = ownedUtxos[2]!;
/** The stranger's minting transaction. */
const T = "e6".repeat(32);
const hexOf = (s: string) => Buffer.from(s, "ascii").toString("hex");
/** The stranger's own Seedelf, named as the policy names one: prefix, tag, the first input's index and id, 32 bytes. */
const GIFT = `5eed0e1f${hexOf("gift")}00${"5a".repeat(32)}`.slice(0, 64);

/** Output 0 of T: the stranger's Seedelf and 1.5 ₳, under a fresh re-randomization of the user's register. */
function planted(): KoiosUtxo {
  const wasm = loadTestWasm();
  const found = registerOf(theirs)!;
  const base = new wasm.Register(found.generator, found.publicValue);
  const fresh = wasm.rerandomize(base);
  const datum = `d8799f5830${fresh.generator}5830${fresh.publicValue}ff`;
  base.free();
  fresh.free();
  return {
    ...theirs,
    tx_hash: T,
    tx_index: 0,
    value: "1500000",
    block_height: 5_300_000,
    inline_datum: { bytes: datum, value: null },
    asset_list: [{ ...theirs.asset_list![0]!, asset_name: GIFT, fingerprint: "asset1strangersgift" }],
  };
}

/** Output 1 of T: 1 ₳ to the user's public account, at an address of it the stranger saw on chain. */
function paidToAccount(): KoiosUtxo {
  const template = koiosPreprod.accounts[phrase12().preprod.stake]!.account_utxos[0]!;
  return { ...template, tx_hash: T, tx_index: 1, value: "1000000", asset_list: [], block_height: 5_300_000 };
}

const out = (bech32: string, cred: string, value: string, asset_list: KoiosTxInfo["outputs"][number]["asset_list"] = []) => ({
  payment_addr: { bech32, cred },
  value,
  asset_list,
});

/** T as Koios lists it: the stranger's coin in; their Seedelf at the contract and 1 ₳ to the account out. */
const mintTx = (key: string, row: { block_height: number; block_time: number }): KoiosTxInfo => ({
  tx_hash: T,
  block_height: row.block_height,
  tx_timestamp: row.block_time,
  fee: "250000",
  inputs: [out("addr_test1_stranger", "57".repeat(28), "10000000")],
  outputs: [
    out(theirs.address, CONTRACT_V1.walletContractHash, "1500000", [{ policy_id: CONTRACT_V1.seedelfPolicyId, asset_name: GIFT, quantity: "1" }]),
    out("addr_test1_mine", key, "1000000"),
  ],
});

/** The Remove form for `seedelf`, as Home opens it: the card it starts on, and what it says. */
function removeForm(seedelf: SeedelfInfo) {
  const html = renderToStaticMarkup(createElement(RemoveSeedelf, { seedelf, onCancel: () => undefined, onSent: () => undefined })).replaceAll(
    "&#x27;",
    "'",
  );
  const checked = [...html.matchAll(/role="radio" aria-checked="true".*?class="token-row__label">([^<]+)</g)].map((m) => m[1]);
  return { html, checked };
}

