// Chunk 51, e1b#1 (the trace verifier's test). The wallet has three boxes in
// v2's 5 ₳ pool, the user presses Bring every box back now, and giveme.my is
// answering every request 429 (its limit for this IP). A 429 is the
// service's answer, not a box's: every other box's withdraw meets the same
// one. Today bringAllBackNow's catch (lovejoin.ts:7407-7414) keeps the reason
// and goes on to the next box, so each run builds every box's withdraw in
// WebAssembly and asks giveme.my once a box, three runs over
// (BRING_FAILED_RUNS) before it stops.
//
// What's right: a run ends at giveme.my's busy answer, as it ends at a lock
// or a withdraw that may have gone, so giveme.my is asked once a run while it
// says it's busy, and three such runs still stop it with the reason, as
// lovejoin-bring-all-back.test.ts's one-box test has it. Driven through the
// worker with the real WebAssembly.

import { describe, expect, it } from "vitest";

import { txInputs } from "../src/background/cbor";
import { Collateral } from "../src/background/collateral";
import type { KoiosUtxo } from "../src/background/koios";
import { BRING_FAILED_RUNS, LovejoinService } from "../src/background/lovejoin";
import { account, AGREES, PASSWORD, POOL } from "./chain-fixtures";
import { txIdOf } from "./fixtures/cbor";
import { busyFor, loadTestWasm, testBalances } from "./fakes";
import { ADA_POOL, ADA_ROWS, adaBox, madeByAdaMix, ownDatum, retiredAlready } from "./v2-pools";

/** Real withdraws are built and measured in WebAssembly: seconds each, more on CI. */
const SLOW = { timeout: 300_000 };

type T = ReturnType<typeof testBalances>;

/** Lovejoin reading v2's 5 ₳ pool beside the classic pool, giveme.my's witness stood in for. */
function pooled(t: T): LovejoinService {
  const wasm = loadTestWasm();
  return new LovejoinService({
    ...t.deps,
    wasm: {
      ...wasm,
      finishLovejoinWithdraw: (request: string) => {
        const { txCbor } = JSON.parse(request) as { txCbor: string };
        return JSON.stringify({ txCbor, txHash: txIdOf(Uint8Array.from(Buffer.from(txCbor, "hex"))) });
      },
    } as typeof wasm,
    collateral: () => new Collateral("https://www.giveme.my/preprod/collateral/", t.collateral.fetch),
    store: t.store,
    pools: async () => [ADA_POOL],
    random: () => 0.5,
  });
}

/** A box of the wallet's in v2's 5 ₳ pool, a mix there having made it five hours ago. */
async function fiveBox(t: T, tx: string): Promise<KoiosUtxo> {
  madeByAdaMix(t.koios, tx.repeat(32));
  return adaBox(tx, await ownDatum(t.wallet), t.clock.now, 5);
}

/** The boxes the withdraws giveme.my was asked about spend, `txhash#index`. */
const withdrawn = (t: T) => t.collateral.asked.flatMap((tx) => txInputs(Uint8Array.from(Buffer.from(tx, "hex"))));

type Sealed = { bringing?: { back: number; left?: number; why?: string; fails?: number; stopped?: true } };
const sealed = async (t: T) => (await t.store.get<Sealed>("lovejoin.preprod"))!;

describe("r51 e1b#1: Bring every box back now while giveme.my answers 429", SLOW, () => {
  it(`asks giveme.my once a run, not once a box, and still stops after ${BRING_FAILED_RUNS} runs that sent nothing`, async () => {
    const t = testBalances();
    await t.wallet.create(account(12).phrase, PASSWORD);
    t.koios.evaluation = AGREES;
    // Past 1.8.0's first run (retireOnce): the run below is the user's own press.
    await retiredAlready(t.store);
    const lj = pooled(t);
    const ours = await Promise.all(["f1", "f2", "f3"].map((tx) => fiveBox(t, tx)));
    t.koios.addedToAccounts.push(...POOL, ...ADA_ROWS, ...ours);
    await lj.status("preprod");
    await lj.bringAllBack("preprod");
    // giveme.my's limit for this IP: every request answered 429, whatever transaction it carries.
    t.collateral.answer = { status: 429, body: { detail: "Too Many Requests" } };
    const perRun: number[] = [];
    for (let run = 1; run <= BRING_FAILED_RUNS; run++) {
      const before = t.collateral.asked.length;
      // The alarm's run, a minute after the last.
      expect(await lj.withdrawDue("preprod")).toEqual([]);
      perRun.push(t.collateral.asked.length - before);
      expect((await sealed(t)).bringing).toMatchObject({ back: 0, left: 3, fails: run, why: expect.any(String) });
      await busyFor(t, 60_000);
    }
    expect((await sealed(t)).bringing?.stopped).toBe(true);
    expect(t.koios.submitted).toEqual([]);
    const boxes = withdrawn(t);
    expect(perRun, `giveme.my requests a run, ${boxes.length} in all over ${new Set(boxes).size} different boxes`).toEqual(
      Array.from({ length: BRING_FAILED_RUNS }, () => 1),
    );
  });
});

// Chunk 51, e2b#1: a mix from the Lovejoin tile whose whole chain went (its deposit, its mix and its return, all on
// chain), paid by a stranger before the runner closes it: the account's address is public from the funding, and a
// session closes only once nothing at it can come back (act). What reaches it then is the stranger's, not the mix's.
// It comes back directly, never in a second chain over the mix's own settings (independent review L17, c421bd29: "a
// mix never starts a second chain"), and the mix still reads as mixed: `mix.skipped`, which the Lovejoin hub shows as
// "Not mixed", says why the mix's own boxes never went in, never why a stranger's later 2 ₳ didn't. The finished twin
// of return-chain-scope.test.ts's "a mix whose chain stopped partway". The real WebAssembly, Lovejoin v2's 5 ₳ pool
// (v2-pools.ts), and fakes of Koios.
import { describe, expect, it } from "vitest";

import type { KoiosUtxo } from "../src/background/koios";
import { detailOf, subOf } from "../src/ui/screens/Lovejoin";
import { account, AGREES, atSession, PASSWORD, sessionsOf } from "./chain-fixtures";
import { testBalances } from "./fakes";
import { ADA, ADA_POOL, ADA_ROWS } from "./v2-pools";

/** Building a chain runs the scripts of every mix in it. */
const CHAINS = { timeout: 120_000 };
const FUNDING = "ab".repeat(32);
/** The mix's return, its chain's last. */
const LAST = "ae".repeat(32);

type Book = { sessions: Array<{ chain: { last: string }; txs: Array<{ kind: string }>; mix: { skipped?: string } }> };

/**
 * Mix session 0 into the 5 ₳ pool whose chain finished: its funding, deposit, mix and return, all on chain, as pump
 * leaves it. `paid`: what a stranger paid its account since.
 */
async function finished(paid: KoiosUtxo[]) {
  const t = testBalances({ pools: [ADA_POOL] });
  await t.wallet.create(account(12).phrase, PASSWORD);
  t.koios.evaluation = AGREES;
  const at = t.clock.now;
  const done = (kind: string, txHash: string) => ({ kind, txHash, at, confirmed: true });
  await t.store.set("sessions.preprod", {
    next: 1,
    sessions: [
      {
        index: 0,
        ownStake: true,
        createdAt: at,
        txs: [done("out", FUNDING), done("deposit", "ac".repeat(32)), done("mix", "ad".repeat(32)), done("back", LAST)],
        mix: { boxes: 1, pool: ADA },
        auto: { approved: { minAmountOut: "0", fund: { lovelace: "15000000", tokens: [] } } },
        chain: { total: 3, last: LAST, at },
      },
    ],
  });
  t.koios.addedToAccounts.push(...paid, ...ADA_ROWS);
  // One wave deep, and its collateral's mix off, as the stopped twin has it: the return asked about is the one that
  // brings back what's at the account.
  await t.deps.preferences.set({ lovejoinDepth: 1, lovejoinCollateral: false });
  return { t, sessions: sessionsOf(t) };
}

describe("a mix whose chain finished, paid by a stranger before it closes (chunk 51, e2b#1)", () => {
  it("brings what reaches its account after back directly, never in another chain", CHAINS, async () => {
    // 40 ₳, and 5 ₳ of ADA alone a chain can put up as its collateral.
    const { t, sessions } = await finished([atSession("c1".repeat(32), 0, "40000000"), atSession("c2".repeat(32), 1, "5000000")]);
    await sessions.advance("preprod", 0, true);
    const book = (await t.store.get<Book>("sessions.preprod"))!;
    expect(book.sessions[0]!.txs.map((x) => x.kind)).toEqual(["out", "deposit", "mix", "back", "back"]);
    expect(book.sessions[0]!.chain.last).toBe(LAST);
    expect(t.koios.submitted).toHaveLength(1);
  });

  it("still reads as mixed once a stranger's 2 ₳ came back and it closed", CHAINS, async () => {
    const stranger = atSession("c3".repeat(32), 0, "2000000");
    const { t, sessions } = await finished([stranger]);
    // The runner brings the 2 ₳ back, directly: no 5 ₳ at the account for a chain's collateral.
    await sessions.advance("preprod", 0, true);
    expect(t.koios.submitted).toHaveLength(1);
    // It lands, spending the 2 ₳, and the next step closes the session.
    t.koios.addedToAccounts.splice(t.koios.addedToAccounts.indexOf(stranger), 1);
    t.koios.confirmations = 1;
    t.clock.now += 60_000;
    await sessions.advance("preprod", 0, true);
    const [view] = await sessions.list("preprod");
    expect(view!.stage).toBe("closed");
    // Its boxes went in and were mixed: Done on the hub, never "Not mixed" (Lovejoin.tsx tagOf reads `mix.skipped`),
    // and its row says so, with no reason it was left out.
    expect({ skipped: view!.mix?.skipped, sub: subOf(view!, t.clock.now), detail: detailOf(view!) }).toEqual({
      skipped: undefined,
      sub: expect.stringMatching(/^In Lovejoin since /),
      detail: undefined,
    });
  });

  it("still reads as mixed when a stranger's 1 ₳ that can't come back is left at its account", CHAINS, async () => {
    const { t, sessions } = await finished([atSession("c4".repeat(32), 0, "1000000")]);
    // Too little to pay its own way back: nothing is sent, it's left behind, and the next step closes the session.
    await sessions.advance("preprod", 0, true);
    expect(t.koios.submitted).toHaveLength(0);
    t.clock.now += 60_000;
    await sessions.advance("preprod", 0, true);
    const [view] = await sessions.list("preprod");
    expect(view!.stage).toBe("closed");
    expect({ skipped: view!.mix?.skipped, sub: subOf(view!, t.clock.now) }).toEqual({
      skipped: undefined,
      sub: expect.stringMatching(/^In Lovejoin since /),
    });
  });
});

// Chunk 51, e2b#2: a finished swap's page says what its return brought back (`received`, chunk 23's second review,
// DX-5) and how it came back (`lovejoinSkipped`: the timeline's last step and the skip callout). A later return of the
// same session, of what a stranger paid its account before it closed, writes both over: sendRecorded replaces
// `received` with each return's own figures, and sendBack writes that return's own skip reason. The closed swap then
// says it received only the stranger's ADA, never its 906.5941 MIN, and that Lovejoin was left out of its return,
// though its own return went through Lovejoin. The real WebAssembly, Lovejoin v2's 5 ₳ pool (v2-pools.ts), and fakes
// of Koios, giveme.my and Minswap, as sessions.test.ts's "places the order once the funding lands, …" and
// swap-lovejoin-way.test.ts run them.
import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { describe, expect, it } from "vitest";

import { DEFAULT_PREFERENCES } from "../src/shared/preferences";
import type { SessionView } from "../src/shared/rpc";
import { NetworkContext } from "../src/ui/network";
import { PreferencesContext } from "../src/ui/preferences";
import { Session } from "../src/ui/screens/Swaps";
import { lovejoinOf } from "./chain-fixtures";
import { ASK, atSession, funded, fundingOutsSpent, MIN, ordered, orderRow, signing, started, SWAP_TX, unlocked, type T } from "./swap-session";
import { ADA_ROWS } from "./v2-pools";

/** Ogmios's answer when the network measures no more than a transaction declares. */
const AGREES = { jsonrpc: "2.0", method: "evaluateTransaction", result: [] };

/** Real chains are built and measured in WebAssembly: seconds each. */
const CHAINS = { timeout: 180_000 };

/** A stranger's payment to session 0's account, made after its own return went. */
const STRANGER = "c9".repeat(32);

/** The swap's proceeds, as a return's figures name them. */
const PROCEEDS = expect.objectContaining({ assetName: MIN.slice(56), quantity: "906594100" });

type Recorded = {
  txs: Array<{ kind: string; txHash: string; confirmed?: boolean }>;
  received?: { lovelace: string; tokens: Array<{ assetName: string; quantity: string }> };
  lovejoinSkipped?: string;
  closedAt?: number;
};

/** Session 0's sealed record, as the runner left it. */
async function record(t: T): Promise<Recorded> {
  return (await t.store.get<{ sessions: Recorded[] }>("sessions.preprod"))!.sessions[0]!;
}

/** The session's page, as a person reads it, balances shown (swap-page.test.ts's `shown`). */
function page(s: SessionView): string {
  return renderToStaticMarkup(
    createElement(
      PreferencesContext.Provider,
      { value: { prefs: DEFAULT_PREFERENCES, loaded: true, set: async () => undefined } },
      createElement(
        NetworkContext.Provider,
        { value: "preprod" },
        createElement(Session, { session: s, reading: false, onRefresh: () => undefined, onBack: () => undefined, onChanged: () => undefined }),
      ),
    ),
  )
    .replace(/<[^>]+>/g, " ")
    .replaceAll("&#x27;", "'")
    .replace(/\s+/g, " ")
    .trim();
}

describe("a finished swap whose account a stranger paid before it closed (chunk 51, e2b#2)", () => {
  it("still says it received what its own return brought back, once the stranger's 2 ₳ came back too", async () => {
    const t = await unlocked();
    const sessions = signing(t);
    await started(sessions);
    funded(t);
    fundingOutsSpent(t);
    // The funding landed: the runner places the order.
    let view = await sessions.advance("preprod", 0, true);
    expect(view.txs.map((x) => x.kind)).toEqual(["out", "swap"]);

    // The order lands and a batcher fills it: everything at the account comes back in one return.
    ordered(t);
    t.koios.spent.add(`${SWAP_TX}#0`);
    t.koios.addedToAccounts.push(atSession("aa".repeat(32), 0, "2000000", [[MIN, "906594100"]]));
    view = await sessions.advance("preprod", 0, true);
    expect(view.txs.map((x) => x.kind)).toEqual(["out", "swap", "back"]);
    expect(t.koios.submitted).toHaveLength(3);
    const own = (await record(t)).received!;
    expect(own.tokens).toContainEqual(PROCEEDS);

    // That return lands. Before the runner's next look would close the session, someone pays its account 2 ₳: its
    // address is on chain since the funding. The runner brings that back too, in a return of its own.
    t.koios.spent.add(`${SWAP_TX}#1`).add(`${"aa".repeat(32)}#0`);
    t.koios.addedToAccounts.push(atSession(STRANGER, 0, "2000000"));
    view = await sessions.advance("preprod", 0, true);
    expect(view.txs.map((x) => x.kind)).toEqual(["out", "swap", "back", "back"]);
    expect(t.koios.submitted).toHaveLength(4);

    // It lands, and the session is over.
    t.koios.spent.add(`${STRANGER}#0`);
    view = await sessions.advance("preprod", 0, true);
    expect(view.stage).toBe("closed");
    // What the swap got: its own return's 906.5941 MIN and ADA, not the stranger's 2 ₳ less a fee alone.
    expect(view.received?.tokens).toContainEqual(PROCEEDS);
    expect(BigInt(view.received?.lovelace ?? "0")).toBeGreaterThanOrEqual(BigInt(own.lovelace));
    expect(page(view)).toMatch(/Received 906\.5941 MIN/);
  });

  it(
    "never says Lovejoin was left out of its return, which went through Lovejoin, for the stranger's 2 ₳ that came back directly",
    CHAINS,
    async () => {
      const t = await unlocked();
      t.koios.evaluation = AGREES;
      t.koios.confirmations = 1;
      const now = t.clock.now;
      const out = "ab".repeat(32);
      const fill = "aa".repeat(32);
      const done = (kind: string, txHash: string, extra = {}) => ({ kind, txHash, at: now, confirmed: true, ...extra });
      // A swap approved to come back through Lovejoin, one wave deep, its order placed and on chain.
      await t.store.set("sessions.preprod", {
        next: 1,
        sessions: [
          {
            index: 0,
            ownStake: true,
            createdAt: now,
            txs: [done("out", out), done("swap", SWAP_TX, { orders: [`${SWAP_TX}#0`] })],
            swap: { ...ASK, amountOut: "906594100", minAmountOut: "902083681" },
            auto: {
              approved: { minAmountOut: "902083681", fund: { lovelace: "16000000", tokens: [] } },
              direct: false,
              lovejoin: { depth: 1, delay: "1-6", box: "5000000" },
            },
          },
        ],
      });
      // Filled: the order is spent, and the account holds the proceeds, the swap's change and its 5 ₳ collateral.
      t.koios.addedToAccounts.push(
        orderRow(SWAP_TX, 0),
        atSession(fill, 0, "2000000", [[MIN, "906594100"]]),
        atSession(SWAP_TX, 1, "12000000"),
        atSession(out, 1, "5000000"),
        ...ADA_ROWS,
      );
      t.koios.spent.add(`${SWAP_TX}#0`);
      // Its collateral's own mix into the 5 ₳ pool is off: the return asked about here is its chain alone.
      await t.deps.preferences.set({ lovejoinCollateral: false });
      const sessions = signing(t, { lovejoin: lovejoinOf(t), sleep: async () => undefined });

      // The runner sees the fill and brings it all back through Lovejoin, as approved: one chain, the return last.
      await sessions.advance("preprod", 0, true);
      let kept = await record(t);
      const kinds = kept.txs.map((x) => x.kind);
      expect(kinds.slice(0, 3)).toEqual(["out", "swap", "deposit"]);
      expect(kinds.at(-1)).toBe("back");
      expect(kept.lovejoinSkipped).toBeUndefined();
      const own = kept.received!;
      expect(own.tokens).toContainEqual(PROCEEDS);

      // All of it is on chain. Before the runner's next look would close the session, a stranger pays its account
      // 2 ₳, too little for a box: it comes back directly, in a return of its own.
      t.koios.spent.add(`${fill}#0`).add(`${SWAP_TX}#1`).add(`${out}#1`);
      t.koios.addedToAccounts.push(atSession(STRANGER, 0, "2000000"));
      await sessions.advance("preprod", 0, true);
      kept = await record(t);
      expect(kept.txs.filter((x) => x.kind === "back")).toHaveLength(2);

      // It lands, and the session is over.
      t.koios.spent.add(`${STRANGER}#0`);
      const view = await sessions.advance("preprod", 0, true);
      expect(view.stage).toBe("closed");
      // Its chain went in and finished: the page's last step would read "Through Lovejoin".
      expect(view.chain).toMatchObject({ cut: false });
      expect(view.chain?.stopped).toBeUndefined();
      // The swap's own return went through Lovejoin: its page never says Lovejoin was left out of it, nor that it
      // received the stranger's ADA alone.
      expect(view.lovejoinSkipped).toBeUndefined();
      const words = page(view);
      expect(words).not.toContain("Lovejoin was left out");
      expect(view.received?.tokens).toContainEqual(PROCEEDS);
      expect(words).toMatch(/Received, besides its boxes in Lovejoin 906\.5941 MIN/);
    },
  );
});

// Chunk 51, finding e3a#2: the connector's pick of a private session's
// collateral (dapp.ts sessionCollateral) is the first UTxO of exactly 5 ₳ with
// no tokens at the session's account, whatever else it carries and whoever
// paid it. The session's own return (sessions.ts) takes only one with no datum
// and no reference script (collateralFits), the funding's first (independent
// review L20, privacy review §2.15). Koios lists an account's UTxOs by
// tx_hash ascending (koios.ts paged), so a stranger's 5 ₳ with a datum, from a
// transaction whose id sorts before the funding's, is listed first: then the
// site is offered the stranger's as collateral, the funding's real 5 ₳ as
// spendable, and a transaction spending the real one isn't flagged. The real
// WebAssembly and fakes of Koios, as dapp.test.ts' private CIP-30 cases.
import { describe, expect, it } from "vitest";

import { Collateral } from "../src/background/collateral";
import { DappService, type DappSession } from "../src/background/dapp";
import type { KoiosUtxo } from "../src/background/koios";
import { Minswap } from "../src/background/minswap";
import { SessionService } from "../src/background/sessions";
import { TxSignError } from "../src/shared/dapp";
import { txIdOf } from "./fixtures/cbor";
import { loadTestWasm, sessionSwap, testBalances, vectors, withdrawPreprod } from "./fakes";

const PASSWORD = "correct horse battery";
const account = (words: number) =>
  vectors("cardano_account.json").find((v) => v.account === 0 && v.phrase.split(" ").length === words)!;
const THEIRS = account(15).preprod.receive_0 as string;
const SLOW = { timeout: 60_000 };

let pages = 0;
const site = (origin = "https://app.example.com"): DappSession => ({ id: `r51e3a2-${++pages}`, origin, title: "Example" });

async function until(check: () => boolean) {
  for (let i = 0; i < 400 && !check(); i++) await new Promise((r) => setTimeout(r, 0));
  expect(check()).toBe(true);
}

async function on() {
  const t = testBalances();
  await t.wallet.create(account(12).phrase, PASSWORD);
  await t.preferences.set({ dappConnector: true, spendRewards: false });
  return t;
}
type T = Awaited<ReturnType<typeof on>>;

/** A UTxO at session 0's account, as Koios lists it. */
function atSession(tx_hash: string, tx_index: number, value: string): KoiosUtxo {
  return {
    ...(sessionSwap.utxo as unknown as KoiosUtxo),
    tx_hash,
    tx_index,
    value,
    payment_cred: sessionSwap.keyHash,
    stake_address: null,
    block_height: 5_000_000,
    asset_list: [],
    is_spent: false,
  } as KoiosUtxo;
}

/** The connector over a session service, as dapp.test.ts' `privately`: giveme.my and the Seedelf proof stood in for. */
function privately(t: T) {
  const wasm = loadTestWasm();
  t.collateral.answer = { status: 200, body: { witness: "a1008182" } };
  const evaluation = withdrawPreprod.amount.evaluation as { result: unknown[] };
  t.koios.evaluation = { ...evaluation, result: evaluation.result.slice(0, 1) };
  const sessions = new SessionService({
    ...t.deps,
    wasm: {
      ...wasm,
      signScriptSpend: (_key: unknown, request: string) => {
        const { txCbor } = JSON.parse(request) as { txCbor: string };
        return JSON.stringify({ txCbor, txHash: txIdOf(Uint8Array.from(Buffer.from(txCbor, "hex"))) });
      },
    } as typeof wasm,
    collateral: () => new Collateral("https://www.giveme.my/preprod/collateral/", t.collateral.fetch),
    store: t.store,
    minswap: () => new Minswap("https://aggr.monorepo-testnet-preprod.minswap.org/aggregator", t.minswap.fetch),
  });
  return new DappService({
    ...t.deps,
    store: t.store,
    sessions,
    lovejoin: t.lovejoin,
    fundingPollMs: 1,
    network: () => "preprod",
    window: t.dappWindow,
    changed: () => undefined,
  });
}

const uint = (n: number) => (n < 24 ? n.toString(16).padStart(2, "0") : `18${n.toString(16).padStart(2, "0")}`);

/** A site's transaction spending `inputs` (`txhash#index`) and paying 4 ₳ to someone else; nothing balances it. */
function siteTx(inputs: string[]) {
  const ins = `8${inputs.length}${inputs.map((o) => `825820${o.slice(0, 64)}${uint(Number(o.slice(65)))}`).join("")}`;
  const outputs = `81825839${loadTestWasm().cip30Address(THEIRS)}1a003d0900`;
  return `84a300${ins}01${outputs}021a00029810a0f5f6`;
}

/** A CIP-30 `TransactionUnspentOutput`'s outpoint: `[[txhash, index], output]`, an index under 24. */
const outpointOf = (hex: string) => `${hex.slice(8, 72)}#${parseInt(hex.slice(72, 74), 16)}`;

/** A stranger's transaction id below any funding's: Koios lists its outputs first. */
const STRANGER = "00".repeat(32);

/**
 * A site connected to session 0, funded with 15 ₳ and its 5 ₳ collateral
 * (`out.txHash#1`), whose account Koios lists as `rows` gives it: the
 * recorded swap's UTxO, the funding's 5 ₳ and the stranger's 5 ₳.
 */
async function connected(t: T, dapp: DappService, stranger: Partial<KoiosUtxo>, strangerFirst: boolean) {
  const s = site();
  const enabling = dapp.call(s, "enable", []);
  await until(() => dapp.approvals().length === 1);
  const out = await dapp.privateBuild(dapp.approvals()[0]!.id, "15000000", []);
  expect(await dapp.answer(dapp.approvals()[0]!.id, true, PASSWORD, { txHash: out.txHash })).toEqual({});
  const theirs = { ...atSession(STRANGER, 0, "5000000"), ...stranger } as KoiosUtxo;
  const swap = atSession(sessionSwap.utxo.tx_hash, sessionSwap.utxo.tx_index, sessionSwap.utxo.value);
  const own = atSession(out.txHash, 1, "5000000");
  t.koios.addedToAccounts.push(...(strangerFirst ? [theirs, swap, own] : [swap, own, theirs]));
  expect(await enabling).toBe(true);
  return { s, own: `${out.txHash}#1`, theirs: `${STRANGER}#0` };
}

/** What the connector tells the site, and whether a transaction spending the funding's 5 ₳ is flagged. */
async function whatTheSiteSees(dapp: DappService, s: DappSession, own: string) {
  const collateral = ((await dapp.call(s, "getCollateral", [])) as string[] | null)?.map(outpointOf) ?? null;
  const utxos = ((await dapp.call(s, "getUtxos", [])) as string[]).map(outpointOf);
  const signing = dapp.call(s, "signTx", [siteTx([own]), false]);
  await until(() => dapp.approvals().length === 1);
  const approval = dapp.approvals()[0]!;
  await dapp.answer(approval.id, false);
  await expect(signing).rejects.toMatchObject({ failure: { code: TxSignError.UserDeclined } });
  return { collateral, utxos, approval };
}

const kinds: Array<[string, Partial<KoiosUtxo>]> = [
  ["an inline datum", { inline_datum: { bytes: "d87980", value: {} } } as Partial<KoiosUtxo>],
  ["a datum hash", { datum_hash: "ee".repeat(32) } as Partial<KoiosUtxo>],
  [
    "a reference script",
    { reference_script: { hash: "ab".repeat(28), size: 6, type: "plutusV3", bytes: "450100002499" } } as unknown as Partial<KoiosUtxo>,
  ],
];

describe("e3a#2: a site session's collateral, with a stranger's 5 ₳ of ADA alone but for a datum or a script", SLOW, () => {
  it("control: listed after the funding's 5 ₳, the stranger's changes nothing", async () => {
    const t = await on();
    const dapp = privately(t);
    const { s, own } = await connected(t, dapp, kinds[0]![1], false);
    const seen = await whatTheSiteSees(dapp, s, own);
    expect(seen.collateral).toEqual([own]);
    expect(seen.utxos).not.toContain(own);
    expect(seen.approval).toMatchObject({ kind: "sign-tx", session: 0, collateralSpent: true });
  });

  it.each(kinds)(
    "listed first, a stranger's 5 ₳ with %s never stands as the session's collateral: the funding's is offered, kept out of getUtxos, and its spend flagged",
    async (_kind, stranger) => {
      const t = await on();
      const dapp = privately(t);
      const { s, own, theirs } = await connected(t, dapp, stranger, true);
      const seen = await whatTheSiteSees(dapp, s, own);
      // The session's return can't put the stranger's up (sessions.ts collateralFits): the connector must agree.
      expect.soft(seen.collateral, "getCollateral").toEqual([own]);
      expect.soft(seen.collateral ?? [], "getCollateral").not.toContain(theirs);
      expect.soft(seen.utxos, "getUtxos").not.toContain(own);
      expect.soft(seen.approval, "signTx's prompt").toMatchObject({ kind: "sign-tx", session: 0, collateralSpent: true });
    },
  );
});

// Chunk 51's whole review, e3b#2: the connect window's private-session form reads the private balance itself
// (`call("balances")`) and states and caps the amount against all of it, what the user locked included, where Home
// hands every other form the unlocked side (`unlocked`) and the funding's build leaves locked UTxOs out (coin-control.ts
// `seedelf`, through script-spend.ts `readContract`). With 100 ₳ held and 60 ₳ of it locked, with a token, the form
// said 100 ₳, took 50 ₳ with Review on and offered the token; the build refuses both.
//
// The worker for real (the 12-word phrase, real WebAssembly, fakes of Koios and giveme.my): its reading, what the
// window is handed, and its build. The window's form over the house's seam (screens-wiring-review-fixes.test.ts):
// ConnectRequest's own effects run during renderToStaticMarkup, `call` answers at once so the reading lands in the same
// render, and the private session's choice and the amount typed start as seeds in their useState.
import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { describe, expect, it, vi } from "vitest";

const seam = vi.hoisted(() => {
  /** A thenable that answers at once: an effect's `.then` lands in the same render. */
  interface Answer {
    then(ok?: ((value: unknown) => unknown) | null, no?: ((error: unknown) => unknown) | null): Answer;
  }
  const answered = (value: unknown): Answer => ({ then: (ok) => (ok ? answered(ok(value)) : answered(value)) });
  const pending: Answer = { then: () => pending };
  const state = {
    /** The components whose own effects run, by name. */
    effects: new Set<string>(),
    answers: new Map<string, unknown>(),
    asked: [] as string[],
    /** A useState seeded: the call right after a run of calls starting as `after`, itself starting as `initial`. */
    seeds: [] as Array<{ after: unknown[]; initial: unknown; value: unknown; used?: true }>,
    initials: [] as unknown[],
    call(type: string): Answer {
      state.asked.push(type);
      return state.answers.has(type) ? answered(state.answers.get(type)) : pending;
    },
    seeded(initial: unknown): unknown {
      const before = state.initials;
      state.initials = [...before, initial];
      for (const seed of state.seeds) {
        if (seed.used || before.length < seed.after.length || !Object.is(initial, seed.initial)) continue;
        const run = before.slice(before.length - seed.after.length);
        if (!seed.after.every((want, i) => Object.is(run[i], want))) continue;
        seed.used = true;
        return seed.value;
      }
      return initial;
    },
  };
  return state;
});

vi.mock("react", async (original) => {
  const react = await original<typeof import("react")>();
  /** Who called the effect: the frame after the seam's own. */
  const caller = () => {
    const frames = (new Error().stack ?? "").split("\n");
    const at = frames.findIndex((f) => f.includes("seamEffect"));
    return /at (?:[\w$]+\.)*([\w$]+)/.exec(frames[at + 1] ?? "")?.[1] ?? "";
  };
  /** The named components' effects, run during the render, again only when a dependency changes. */
  function seamEffect(run: () => void | (() => void), deps?: readonly unknown[]) {
    const last = react.useRef<readonly unknown[] | null>(null);
    const cleanup = react.useRef<void | (() => void)>(undefined);
    if (!seam.effects.has(caller())) return;
    const was = last.current;
    if (was && (!deps || (deps.length === was.length && deps.every((d, i) => Object.is(d, was[i]))))) return;
    last.current = deps ?? [];
    cleanup.current?.();
    cleanup.current = run();
  }
  return {
    ...react,
    useEffect: seamEffect,
    useLayoutEffect: seamEffect,
    useState: (initial?: unknown) => react.useState(seam.seeded(initial)),
  };
});
vi.mock("../src/ui/background", async (original) => ({
  ...(await original<typeof import("../src/ui/background")>()),
  call: (type: string) => seam.call(type),
}));

