describe("r51 e3b#3: requests that come in behind a private session's funding that's sent", () => {
  it("are counted on the window, with Decline all, before closing it declines them", async () => {
    const t = testBalances();
    await t.wallet.create(account.phrase, PASSWORD);
    await t.preferences.set({ dappConnector: true, spendRewards: false });

    // The session service's sending and reading, stood in for: sent, and not seen by Koios until `landed`.
    const landed = { now: false };
    Object.assign(t.sessions as unknown as Record<string, unknown>, {
      siteOutSubmit: async () => ({ index: 0, pending: {} }),
      siteAccount: async () => ({ address: "", reward: "", keyHash: "00".repeat(28) }),
      accountUtxos: async () => (landed.now ? [{}] : []),
      fundingSeen: async () => "landed",
    });

    // Site B is connected to the public account.
    const b = site("https://b.example");
    const enablingB = t.dapp.call(b, "enable", []);
    await until(() => t.dapp.approvals().length === 1);
    await t.dapp.answer(t.dapp.approvals()[0]!.id, true);
    expect(await enablingB).toBe(true);

    // Site A connects to a private session: its funding is sent from the window and waits for the chain.
    const a = site("https://a.example");
    const enablingA = t.dapp.call(a, "enable", []);
    await until(() => t.dapp.approvals().length === 1);
    const connectA = t.dapp.approvals()[0]!;
    expect(await t.dapp.answer(connectA.id, true, PASSWORD, { txHash: TX })).toEqual({});
    expect(t.dapp.approvals()).toMatchObject([{ id: connectA.id, kind: "connect", funding: { index: 0, txHash: TX } }]);

    // Meanwhile B asks to sign and C to connect: each brings the window to the front.
    const shown = t.dappWindow.shown;
    const signingB = heard(t.dapp.call(b, "signData", [t.deps.wasm.cip30Address(OWN), hex("Sign in")]));
    const enablingC = heard(t.dapp.call(site("https://c.example"), "enable", []));
    await until(() => t.dapp.approvals().length === 3);
    expect(t.dappWindow.shown).toBe(shown + 2);

    // The window, from what the worker lists: it says two more wait, and offers Decline all, as every other screen does.
    seam.approvals = t.dapp.approvals();
    const html = renderToStaticMarkup(createElement(DappApprovals));
    const page = text(html);
    expect.soft(page, "the window shows the funding and nothing of what waits behind it").toContain("1 of 3 waiting");
    expect.soft(page).toContain("Decline all");
    expect.soft(html).toContain('data-testid="dapp-queue"');

    // The user closes it, as the funding's screen says they can: the funding goes on; B and C are declined.
    t.dappWindow.open = false;
    await t.dapp.windowClosed();
    expect(t.dapp.approvals()).toMatchObject([{ id: connectA.id, funding: { index: 0, txHash: TX } }]);
    expect(await signingB).toEqual({ code: DataSignError.UserDeclined, info: "The user declined." });
    expect(await enablingC).toEqual({ code: APIError.Refused, info: "The user declined." });
    // And C is turned away, as a site declined is.
    await expect(t.dapp.call(site("https://c.example"), "enable", [])).rejects.toMatchObject({
      failure: { code: APIError.Refused, info: "The user declined this site just now. It can ask again in 10 s." },
    });

    // The funding lands: A connects, and nothing waits.
    landed.now = true;
    expect(await enablingA).toBe(true);
    expect(t.dapp.approvals()).toEqual([]);
  });
});

// Chunk 51, e3b#4: an approved request whose approval then fails is out of the worker's list by the time its error
// comes back (dapp.ts `answer`: taken out, the windows told, then `approve` refuses), and the connector's window keeps
// that error, one state for every request (DappApprovals.tsx's `error`), under the request after it: A's refusal sits
// in B's foot, role="alert", over B's Decline and Sign, and nothing says it was A's. Once nothing's left, the window
// keeps it on purpose (its close timer waits on `!error`), which the last two cases pin.
//
// The worker is the real one (tests/fakes.ts): site X's transaction, then site Y's, wait, and the user locks the UTxO
// X's spends from the main window meanwhile (dapp-site-english.test.ts's case), then presses Sign on X's.
//
// Vitest has no DOM, and the house seam (screens-wiring-review-fixes.test.ts) can't carry a press past its await, so
// the window runs over a small hooks runtime of this test's own, behind `vi.mock("react")`: DappApprovals is called as
// the function it is, its hooks kept from one draw to the next, its effects run after each draw as React runs them
// (the last run's cleanup first, again only when a dependency changes), and state set by a press, an answer or a timer
// draws it again. React itself then renders what it drew, its children with React's own hooks, to read the error it
// shows. The worker's answer comes back on its own port and its "changed" on another, so either can land first: each
// order is run.
import { createElement, isValidElement, type ReactElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { afterEach, describe, expect, it, vi } from "vitest";

import type { DappSession } from "../src/background/dapp";
import type { Requests } from "../src/shared/rpc";

const hooks = vi.hoisted(() => {
  interface Slot {
    has?: boolean;
    value?: unknown;
    deps?: readonly unknown[];
    cleanup?: unknown;
  }
  const moved = (was: readonly unknown[] | undefined, now: readonly unknown[] | undefined) =>
    !was || !now || was.length !== now.length || now.some((d, i) => !Object.is(d, was[i]));
  const rt = {
    /** The test is drawing the window: its hooks are these then, React's own otherwise. */
    drawing: false,
    slots: [] as Slot[],
    at: 0,
    /** State was set since the last draw. */
    dirty: false,
    /** The draw's effects, run once it's made, as React runs them after it commits. */
    effects: [] as Array<() => void>,
    slot(): Slot {
      return (rt.slots[rt.at++] ??= {});
    },
    useReducer(reducer: (state: unknown, action: unknown) => unknown, arg: unknown, init?: (arg: unknown) => unknown) {
      const s = rt.slot();
      if (!s.has) {
        s.has = true;
        const dispatch = (action: unknown) => {
          const [was] = s.value as [unknown, unknown];
          const next = reducer(was, action);
          if (Object.is(next, was)) return;
          s.value = [next, dispatch];
          rt.dirty = true;
        };
        s.value = [init ? init(arg) : arg, dispatch];
      }
      return s.value;
    },
    useState(initial: unknown) {
      return rt.useReducer(
        (was, action) => (typeof action === "function" ? (action as (was: unknown) => unknown)(was) : action),
        initial,
        (arg) => (typeof arg === "function" ? (arg as () => unknown)() : arg),
      );
    },
    useRef(initial: unknown) {
      const s = rt.slot();
      if (!s.has) {
        s.has = true;
        s.value = { current: initial };
      }
      return s.value;
    },
    useMemo(make: () => unknown, deps?: readonly unknown[]) {
      const s = rt.slot();
      if (!s.has || moved(s.deps, deps)) {
        s.has = true;
        s.value = make();
        s.deps = deps;
      }
      return s.value;
    },
    useCallback(fn: unknown, deps?: readonly unknown[]) {
      return rt.useMemo(() => fn, deps);
    },
    useEffect(run: () => unknown, deps?: readonly unknown[]) {
      const s = rt.slot();
      if (s.has && !moved(s.deps, deps)) return;
      s.has = true;
      s.deps = deps;
      rt.effects.push(() => {
        if (typeof s.cleanup === "function") (s.cleanup as () => void)();
        s.cleanup = run();
      });
    },
    useContext(context: unknown) {
      return (context as { _currentValue: unknown })._currentValue;
    },
    useId() {
      const s = rt.slot();
      if (!s.has) {
        s.has = true;
        s.value = `:r51-${rt.at}:`;
      }
      return s.value;
    },
    useSyncExternalStore(_subscribe: unknown, snapshot: () => unknown) {
      return snapshot();
    },
    /** Runs every cleanup, as unmounting does, and forgets the window. */
    unmount() {
      for (const s of rt.slots) if (typeof s.cleanup === "function") (s.cleanup as () => void)();
      rt.slots = [];
      rt.effects = [];
      rt.dirty = false;
    },
  };
  return rt;
});

const harness = vi.hoisted(() => ({
  /** What the window's `call` asks the worker: `openWindow` sets it. */
  call: (() => new Promise<never>(() => undefined)) as (type: string, payload: unknown) => Promise<unknown>,
  /** The window's `onDappChanged` listeners. */
  heard: new Set<() => void>(),
  /** Every request the window made, by name. */
  asked: [] as string[],
}));

vi.mock("react", async (original) => {
  const react = await original<typeof import("react")>();
  const theirs = react as unknown as Record<string, (...args: unknown[]) => unknown>;
  const ours: Record<string, (...args: never[]) => unknown> = {
    useState: hooks.useState,
    useReducer: hooks.useReducer,
    useRef: hooks.useRef,
    useMemo: hooks.useMemo,
    useCallback: hooks.useCallback,
    useEffect: hooks.useEffect,
    useLayoutEffect: hooks.useEffect,
    useInsertionEffect: hooks.useEffect,
    useContext: hooks.useContext,
    useId: hooks.useId,
    useSyncExternalStore: hooks.useSyncExternalStore,
  };
  const swapped = Object.entries(ours).map(([name, mine]) => [
    name,
    (...args: unknown[]) => (hooks.drawing ? (mine as (...a: unknown[]) => unknown)(...args) : theirs[name]!(...args)),
  ]);
  return { ...react, ...Object.fromEntries(swapped) };
});

