    expect.soft(entries.map((e) => e.txHash), "B's private Activity: transactions").toEqual([bOwn.tx_hash]);
    expect.soft(entries.find((e) => e.txHash === bOwn.tx_hash)?.origin, "B's own UTxO: its history").toEqual(UNKNOWN);
