// Chunk 51, e4b#2 (the trace verifier's test). A site's signature waits in the
// connector's window, the user walks away, and auto-lock locks the wallet. A
// lock leaves what sites wait for in the worker's memory (dapp.ts
// `stateChanged` returns for "locked" with `waiting` untouched), so the user
// can unlock and answer. But `dapp-approvals` (handlers.ts:433) has no lock
// check, so any of the wallet's own pages, DevTools on the window that now
// shows Unlock included, still reads the whole prompt: the site, the
// account's own outputs, and which of the wallet's other accounts the
// transaction pays (`ties`), knowledge that comes from the sealed records and
// the keys. Its neighbours `dapp-declined` and `dapp-let-ask` refuse while
// locked. The right behaviour: refused while locked, as `dapp-declined` is,
// and the same request back once unlocked.
import { describe, expect, it } from "vitest";

import { type DappSession } from "../src/background/dapp";
import { handle, type Context } from "../src/background/handlers";
import { NetworkChoice } from "../src/background/preferences";
import { AUTO_LOCK_MS } from "../src/background/wallet";
import type { DappApproval } from "../src/shared/rpc";
import { loadTestWasm, testBalances, vectors } from "./fakes";

const PASSWORD = "correct horse battery";
const LOCKED = "The wallet is locked.";
const account = (words: number) =>
  vectors("cardano_account.json").find((v) => v.account === 0 && v.phrase.split(" ").length === words)!;

const site: DappSession = { id: "r51-e4b-2", origin: "https://dex.example", title: "Example DEX" };

async function until(check: () => boolean) {
  for (let i = 0; i < 200 && !check(); i++) await new Promise((r) => setTimeout(r, 0));
  expect(check()).toBe(true);
}

// A site's transaction, as dapp-ties-accounts.test.ts builds one: it spends `inputs` and pays 4 ₳ to each address.
const uint = (n: number) => (n < 24 ? n.toString(16).padStart(2, "0") : `18${n.toString(16).padStart(2, "0")}`);
const outpoints = (list: string[]) => `8${list.length}${list.map((o) => `825820${o.slice(0, 64)}${uint(Number(o.slice(65)))}`).join("")}`;
const bytesOf = (hex: string) => `58${(hex.length / 2).toString(16).padStart(2, "0")}${hex}`;
function paying(inputs: string[], to: string[]) {
  const outputs = `8${to.length}${to.map((a) => `82${bytesOf(a)}1a003d0900`).join("")}`;
  return `84a300${outpoints(inputs)}01${outputs}021a00029810a0f5f6`;
}

/** The 12-word wallet with three public accounts, the connector on. */
async function on() {
  const t = testBalances();
  await t.wallet.create(account(12).phrase, PASSWORD);
  await t.accounts.recordFirst();
  await t.accounts.add(1);
  await t.accounts.add(2);
  await t.preferences.set({ dappConnector: true, spendRewards: false });
  return t;
}
type T = Awaited<ReturnType<typeof on>>;

/** What the worker hands `handle` for a request from one of the wallet's pages (sw.ts answerUi). */
function context(t: T): Context {
  const { wallet, session, balances, moveIn, mint, transfer, withdraw, send, pending, contacts, activity, coins, staking, preferences, prices, nftImages, dapp, sessions, lovejoin, launch, accounts, dataParts } =
    t;
  return {
    wasm: loadTestWasm(),
    wallet,
    session,
    balances,
    moveIn,
    mint,
    transfer,
    withdraw,
    send,
    pending,
    contacts,
    activity,
    coins,
    staking,
    preferences,
    prices,
    nftImages,
    dapp,
    sessions,
    lovejoin,
    launch,
    accounts,
    dataParts,
    connector: async (on) => on,
    version: "1.0.0",
    network: "preprod",
    networks: ["preprod"],
    networkChoice: new NetworkChoice(t.local, ["preprod"]),
  };
}

/** A request from one of the wallet's pages, as ui-port.ts replies to it: its value, or its refusal's words. */
const asked = (p: Promise<unknown>) =>
  p.then(
    (value) => ({ value }),
    (e: Error) => ({ error: e.message }),
  );

describe("chunk 51, e4b#2: dapp-approvals while locked", () => {
  it("is refused while the wallet is locked, as dapp-declined is, and the request is back once unlocked", { timeout: 30_000 }, async () => {
    const t = await on();
    const ctx = context(t);

    // The site connects to the public account (the dApp account, index 0).
    const enabling = t.dapp.call(site, "enable", []);
    await until(() => t.dapp.approvals().length === 1);
    await t.dapp.answer(t.dapp.approvals()[0]!.id, true);
    expect(await enabling).toBe(true);
    await t.balances.get("preprod");
    const [own] = (await t.coins.lists("preprod")).cardano;

    // It asks to sign a transaction that pays Account 3 (index 2): the prompt ties the two accounts.
    const { wasm } = t.deps;
    const third = await t.wallet.withAccount(2, ({ cardano }) => wasm.cip30Address(cardano.receiveAddress(wasm.Network.Preprod, 0)));
    const signing = t.dapp.call(site, "signTx", [paying([`${own!.txHash}#${own!.index}`], [third]), false]);
    signing.catch(() => undefined);
    await until(() => t.dapp.approvals().length === 1);
    const shown = t.dapp.approvals()[0]! as Extract<DappApproval, { kind: "sign-tx" }>;
    expect(shown.kind).toBe("sign-tx");
    expect(shown.ties).toEqual([{ account: 2 }]);

    // The user walks away: auto-lock locks the wallet at the next look (wallet.ts load), and the worker tells the
    // connector (sw.ts wires the wallet's `changed` to `dapp.stateChanged`).
    t.clock.now += AUTO_LOCK_MS + 1;
    expect(await t.wallet.state()).toBe("locked");
    await t.dapp.stateChanged();
    // What the site waits for is kept for the unlock: by design, not the finding.
    expect(t.dapp.approvals()).toHaveLength(1);

    // Its neighbour refuses while locked: which sites were turned away is private.
    expect(await asked(handle({ type: "dapp-declined" }, ctx))).toEqual({ error: LOCKED });
    // The finding: the waiting prompt, with its ties to the wallet's other accounts, should be refused the same way.
    expect(await asked(handle({ type: "dapp-approvals" }, ctx))).toEqual({ error: LOCKED });

    // Unlocked again, the request is there to answer, as before the lock.
    expect(await t.wallet.unlock(PASSWORD)).toMatchObject({ unlocked: true });
    await t.dapp.stateChanged();
    const back = await asked(handle({ type: "dapp-approvals" }, ctx));
    expect(back).toMatchObject({ value: [{ id: shown.id, kind: "sign-tx", ties: [{ account: 2 }] }] });
    await t.dapp.answer(shown.id, false);
    await expect(signing).rejects.toMatchObject({ failure: { info: "The user declined." } });
  });
});

// Chunk 51, finding e5#1 (merged into r2a#1, whose core test is seedelf-core/tests/r51_r2a_1.rs).
//
// The extension's side of it. Send's and Make public's To field (resolve-destination, resolveDestination,
// checkPayable, then WebAssembly's checkPayableAddress) and Contacts (contacts.ts check, checkPayable) refuse a key
// address whose stake part is a script (CIP-19 header type 2, addr_test1y…) as "That's a script's address … could be
// locked there for good", though only its payment key can spend it and the ledger takes the output with no datum.
// And they call a Byron address "not a Cardano address".
//
// The right behaviour, asserted here: the type-2 address is read as anyone's payable address, passes WebAssembly's own
// check (which public Send's and Make public's builders run again), and is saved as a contact; a script payment part
// is still a script's address; and a Byron address is never called no Cardano address (Make public can't pay one,
// since a script's transaction can't carry a Byron output, but it is an address).
import { describe, expect, it } from "vitest";

import { bech32, bech32Bytes } from "./fixtures/bech32";
import { loadTestWasm, testBalances, vectors } from "./fakes";

const PASSWORD = "correct horse battery";
const account = (words: number) =>
  vectors("cardano_account.json").find((v) => v.account === 0 && v.phrase.split(" ").length === words)!;
/** The 15-word phrase's receive address: someone else's base address, payment key and stake key (header 0x00). */
const THEIRS = account(15).preprod.receive_0 as string;

/** THEIRS's own 56 bytes of hashes under another header: 0x20 reads its stake key hash as a script hash. */
function withHeader(header: number): string {
  const bytes = Uint8Array.from(bech32Bytes(THEIRS));
  bytes[0] = header;
  return bech32("addr_test", bytes);
}
/** CIP-19 type 2 on a test network: THEIRS's payment key, a script (a multisig's stake script, say) as its stake part. */
const KEY_STAKED_BY_SCRIPT = withHeader(0x20);
/** CIP-19 type 1: a script's payment part, a key's stake part. A script's address indeed. */
const SCRIPT_STAKED_BY_KEY = withHeader(0x10);
/** A mainnet Byron (Icarus) address: pallas-addresses 0.35.1's own test vector (src/byron.rs). */
const BYRON = "Ae2tdPwUPEZLs4HtbuNey7tK4hTKrwNwYtGqp7bDfCy2WdR3P6735W5Yfpe";

async function unlocked() {
  const t = testBalances();
  await t.wallet.create(account(12).phrase, PASSWORD);
  return t;
}

/** What a promise gives, or the words it's refused with. */
const outcome = <T>(p: Promise<T>) => p.then((value) => value as T | string, (e: Error) => e.message);

describe("r51 e5#1: a key address whose stake part is a script", () => {
  it("control: the fixture's addresses are well formed, a key/key address is anyone's, a script payment part is a script's", async () => {
    const t = await unlocked();
    const bytes = bech32Bytes(THEIRS);
    expect([bytes.length, bytes[0]]).toEqual([57, 0x00]);
    expect(bech32("addr_test", bytes)).toBe(THEIRS);
    expect(KEY_STAKED_BY_SCRIPT.startsWith("addr_test1y")).toBe(true);
    expect(SCRIPT_STAKED_BY_KEY.startsWith("addr_test1z")).toBe(true);
    expect(await t.withdraw.resolve("preprod", THEIRS)).toEqual({ address: THEIRS, own: false });
    await expect(t.withdraw.resolve("preprod", SCRIPT_STAKED_BY_KEY)).rejects.toThrow("That's a script's address.");
  });

  it("is read as anyone's payable address in Send's and Make public's To field", async () => {
    const t = await unlocked();
    expect(await outcome(t.withdraw.resolve("preprod", KEY_STAKED_BY_SCRIPT))).toEqual({
      address: KEY_STAKED_BY_SCRIPT,
      own: false,
    });
    expect(t.koios.calls).toHaveLength(0);
  });

  it("passes WebAssembly's own check, which public Send's and Make public's builders run again", () => {
    const wasm = loadTestWasm();
    let refused: string | undefined;
    try {
      wasm.checkPayableAddress(KEY_STAKED_BY_SCRIPT, wasm.Network.Preprod);
    } catch (e) {
      refused = e instanceof Error ? e.message : String(e);
    }
    expect(refused).toBeUndefined();
  });

  it("is saved as a contact", async () => {
    const t = await unlocked();
    const saved = await outcome(
      t.contacts
        .save("preprod", { name: "Carol", value: KEY_STAKED_BY_SCRIPT })
        .then((list) => list.map((c) => [c.name, c.kind, c.value])),
    );
    expect(saved).toEqual([["Carol", "address", KEY_STAKED_BY_SCRIPT]]);
  });
});

describe("r51 e5#1: a Byron address", () => {
  it("is never called no Cardano address", async () => {
    const t = await unlocked();
    // Pinned: what isn't an address at all still says so.
    await expect(t.withdraw.resolve("mainnet", "nope")).rejects.toThrow("isn't a Cardano address");
    const said = await outcome(t.withdraw.resolve("mainnet", BYRON));
    expect(typeof said === "string" ? said : "").not.toContain("isn't a Cardano address");
  });
});

// Chunk 51, e5#2: a Make public to another of the user's own public accounts, made while the wallet is on account 0
// (the Your accounts picker, or account 1's address pasted). It's a private spend: the one-time key signs, giveme.my
// lends the collateral, and it touches nothing of account 0. Once it lands, only the private side should be read
// again, as privacy.md says ("When a private spend lands, the wallet reads only the private side again ... What
// touches the account (... a Make public or a removal to it ...) and Refresh still read both") and as pending.ts's
// header and `forgetReading` say: Koios asked about the account on screen in the second a private transaction lands
// ties the two by timing, on a shared IP too (privacy review §2.9). pending.ts `paysAccount` reads `own`, true for
// every account the wallet knows since 11d6ec3f, as the account on screen, so the landing drops the whole reading and
// Home's reload asks Koios about account 0 at once. The real WebAssembly on the 12-word phrase's synthetic Seedelf
// UTxOs, and fakes of Koios and giveme.my.
import { describe, expect, it } from "vitest";

import { Collateral } from "../src/background/collateral";
import { WithdrawService } from "../src/background/withdraw";
import { SESSION_BALANCES_PREFIX, SESSION_PRIVATE_STALE_PREFIX } from "../src/background/wallet";
import type { WithdrawSummary } from "../src/shared/rpc";
import { txIdOf } from "./fixtures/cbor";
import { koiosPreprod, loadTestWasm, testBalances, vectors } from "./fakes";

const PASSWORD = "correct horse battery";
/** The 12-word phrase: the fixture's Seedelf UTxOs are its own. */
const PHRASE = vectors("cardano_account.json").find((v) => v.account === 0 && v.phrase.split(" ").length === 12)!.phrase as string;
/** Each Make public is built and measured in WebAssembly. */
const SLOW = { timeout: 120_000 };

/** A wallet on account 0 that knows account 1 too (Add account, which asks nobody anything), Home's first reading kept. */
async function unlocked() {
  const t = testBalances();
  await t.wallet.create(PHRASE, PASSWORD);
  await t.accounts.add(1);
  await t.balances.get("preprod");
  return t;
}
type T = Awaited<ReturnType<typeof unlocked>>;

const preprod = (t: T) => t.deps.wasm.Network.Preprod;
const receive0 = (t: T, index: number) => t.wallet.withAccount(index, ({ cardano }) => cardano.receiveAddress(preprod(t), 0));
const stakeOf = (t: T, index: number) => t.wallet.withAccount(index, ({ cardano }) => cardano.stakeAddress(preprod(t)));

/** Makes 5 ₳ public to `to` through the worker's own build and Send; giveme.my's witness and the signing stood in for. */
async function makePublic(t: T, to: string): Promise<WithdrawSummary> {
  const summary = await t.withdraw.build("preprod", [{ to, lovelace: "5000000", tokens: [] }]);
  t.collateral.answer = { status: 200, body: { witness: "a1008182" } };
  const wasm = loadTestWasm();
  const service = new WithdrawService({
    ...t.deps,
    wasm: {
      ...wasm,
      signScriptSpend: (_key: unknown, request: string) =>
        JSON.stringify({ txCbor: (JSON.parse(request) as { txCbor: string }).txCbor, txHash: summary.txHash }),
    } as typeof wasm,
    collateral: () => new Collateral("https://www.giveme.my/preprod/collateral/", t.collateral.fetch),
  });
  expect(await service.submit("preprod", summary.txHash)).toMatchObject({ kind: "withdraw", txHash: summary.txHash, confirmations: null });
  expect(t.koios.submitted.map((b) => txIdOf(b))).toEqual([summary.txHash]);
  return summary;
}

/**
 * The watch sees it land, as Home's 15 s ask does, and Home reads the balances at once (Home.tsx `watch`:
 * `if (p.confirmations !== null || p.dropped) void load(false)`). What the landing left of the reading, and what that
 * read asked Koios about the public accounts.
 */
async function landsAndHomeReads(t: T) {
  t.koios.confirmations = 1;
  expect(await t.pending.pending("preprod")).toMatchObject({ confirmations: 1 });
  const accountSideKept = (await t.session.get(SESSION_BALANCES_PREFIX + "preprod")) !== undefined;
  const privateSideBehind = (await t.session.get(SESSION_PRIVATE_STALE_PREFIX + "preprod")) === true;
  const from = t.koios.calls.length;
  await t.balances.get("preprod");
  const calls = t.koios.calls.slice(from);
  const names = new Map([
    [await stakeOf(t, 0), "account 0"],
    [await stakeOf(t, 1), "account 1"],
  ]);
  const accountAsked = calls
    .filter(
      (c) =>
        ["account_addresses", "account_info"].includes(c.path) ||
        (c.path === "credential_utxos" && !(c.body._payment_credentials as string[]).includes(koiosPreprod.wallet_contract)),
    )
    .map((c) => c.path);
  const stakesAsked = [...new Set(calls.flatMap((c) => (c.body?._stake_addresses as string[] | undefined) ?? []))].map(
    (s) => names.get(s) ?? s,
  );
  return { accountSideKept, privateSideBehind, accountAsked, stakesAsked };
}

describe("chunk 51 e5#2: a Make public to another of your own accounts, once it lands", () => {
  it("reads only the private side again: Koios hears nothing of the account on screen", SLOW, async () => {
    const t = await unlocked();
    const other = await receive0(t, 1);
    const summary = await makePublic(t, other);
    // It pays account 1, while the wallet is on account 0.
    expect(summary.payments[0]).toMatchObject({ address: other, own: true, ownAccount: 1 });
    expect(await t.wallet.withKeys(({ account }) => account)).toBe(0);

    expect(await landsAndHomeReads(t)).toEqual({ accountSideKept: true, privateSideBehind: true, accountAsked: [], stakesAsked: [] });
  });

  it("control: a Make public to the account on screen reads it again, as privacy.md says", SLOW, async () => {
    const t = await unlocked();
    const own = await receive0(t, 0);
    const summary = await makePublic(t, own);
    expect(summary.payments[0]).toMatchObject({ address: own, own: true, ownAccount: 0 });

    const after = await landsAndHomeReads(t);
    expect(after.accountSideKept).toBe(false);
    expect(after.accountAsked).toContain("account_addresses");
    expect(after.stakesAsked).toContain("account 0");
  });
});

